def meets_basic_password_policy(s):
    if len(s) < 8:
        return False
    return (any(c.isupper() for c in s) and any(c.islower() for c in s)
            and any(c.isdigit() for c in s))

def meets_strict_password_policy(s):
    if len(s) < 10:
        return False
    if any(c.isspace() for c in s):
        return False
    specials = set('!@#$%^&*')
    return (any(c.isupper() for c in s) and any(c.islower() for c in s)
            and any(c.isdigit() for c in s) and any(c in specials for c in s))

def has_no_triple_repeated_chars(s):
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
            if count >= 3:
                return False
        else:
            count = 1
    return True

def password_excludes_username(password, username):
    if len(password) < 8:
        return False
    return username.lower() not in password.lower()

def meets_min_digit_count_policy(s):
    if any(c.isspace() for c in s):
        return False
    if not (6 <= len(s) <= 20):
        return False
    return sum(c.isdigit() for c in s) >= 2

def is_not_common_password(s, common_list):
    if len(s) < 8:
        return False
    return s.lower() not in {x.lower() for x in common_list}

def has_digit_not_at_edges(s):
    if len(s) < 3:
        return False
    return any(c.isdigit() for c in s[1:-1])

def meets_length_no_whitespace_policy(s):
    if not (8 <= len(s) <= 32):
        return False
    return not any(c.isspace() for c in s)

def has_no_sequential_run(s):
    run = 1
    for i in range(1, len(s)):
        if ord(s[i]) == ord(s[i - 1]) + 1:
            run += 1
            if run >= 3:
                return False
        else:
            run = 1
    return True

def is_valid_iso_date(s):
    parts = s.split('-')
    if len(parts) != 3:
        return False
    y, m, d = parts
    if not (len(y) == 4 and y.isdigit() and len(m) == 2 and m.isdigit() and len(d) == 2 and d.isdigit()):
        return False
    year, month, day = int(y), int(m), int(d)
    if not (1 <= year <= 9999 and 1 <= month <= 12):
        return False
    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    days_in_month = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    return 1 <= day <= days_in_month[month - 1]

def is_valid_24h_time(s):
    parts = s.split(':')
    if len(parts) != 3:
        return False
    h, m, sec = parts
    if not (len(h) == 2 and h.isdigit() and len(m) == 2 and m.isdigit() and len(sec) == 2 and sec.isdigit()):
        return False
    return 0 <= int(h) <= 23 and 0 <= int(m) <= 59 and 0 <= int(sec) <= 59

def is_valid_24h_time_short(s):
    parts = s.split(':')
    if len(parts) != 2:
        return False
    h, m = parts
    if not (len(h) == 2 and h.isdigit() and len(m) == 2 and m.isdigit()):
        return False
    return 0 <= int(h) <= 23 and 0 <= int(m) <= 59
